(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x * 0.02 + t * 0.3) * 15 + Math.cos(y * 0.015 - t * 0.2) * 10;
  const w1y = Math.cos(y * 0.02 - t * 0.25) * 15 + Math.sin(x * 0.018 + t * 0.35) * 10;
  const sx = x + w1x, sy = y + w1y;
  const w2x = Math.sin(sx * 0.025 - t * 0.15) * 8 + Math.cos(sy * 0.03 + t * 0.1) * 6;
  const w2y = Math.cos(sy * 0.028 + t * 0.18) * 8 + Math.sin(sx * 0.022 - t * 0.12) * 6;
  const wx = sx + w2x, wy = sy + w2y;
  const src = [
    [160+Math.sin(t*0.6)*100, 80+Math.cos(t*0.4)*50, 0.08, 2.0],
    [320+Math.cos(t*0.5)*100, 160+Math.sin(t*0.7)*50, 0.1, 1.7],
    [240+Math.sin(t*0.3+2)*140, 120+Math.cos(t*0.5+1)*90, 0.06, 2.3],
    [120+Math.cos(t*0.8+1)*80, 180+Math.sin(t*0.6+3)*60, 0.12, 1.5],
    [360+Math.sin(t*0.4+4)*90, 60+Math.cos(t*0.9+2)*70, 0.07, 2.6],
    [240+Math.cos(t*0.35+5)*120, 200+Math.sin(t*0.55)*80, 0.09, 1.9],
    [200+Math.sin(t*0.7+1)*60, 140+Math.cos(t*0.3+2)*40, 0.18, 3.2],
    [280+Math.cos(t*0.45+3)*70, 100+Math.sin(t*0.65+1)*50, 0.15, 2.8],
    [150+Math.sin(t*0.55+4)*50, 60+Math.cos(t*0.75+3)*35, 0.2, 3.5],
    [340+Math.cos(t*0.38+2)*55, 190+Math.sin(t*0.48+4)*45, 0.16, 3.0]
  ];
  let aS = 0, iS = 0, aH = 0, iH = 0;
  for (let k = 0; k < src.length; k++) {
    const [sX, sY, f, sp] = src[k];
    const d = Math.sqrt((wx-sX)**2 + (wy-sY)**2);
    const wave = Math.sin(d*f - t*sp);
    const iwave = Math.sin(d*f*0.7 + t*sp*0.6 + 1.5);
    if (k < 6) { aS += wave; iS += iwave; }
    else { aH += wave; iH += iwave; }
  }
  const act = aS/6 + aH*0.4/4, inh = iS/6 + iH*0.4/4;
  const bg1 = (Math.sin(wx*0.04+wy*0.025+t*0.8) + Math.sin(wx*0.03-wy*0.04+t*1.1))/2;
  const bg2 = Math.sin((wx+wy)*0.12+t*2.5)*0.2 + Math.sin((wx-wy)*0.1-t*2)*0.2;
  const bg3 = Math.sin(wx*0.08+wy*0.06-t*0.5)*0.15 + Math.sin(wx*0.05-wy*0.09+t*0.7)*0.15;
  const bg = bg1 + bg2 + bg3;
  const dist = Math.sqrt((wx-cx)**2 + (wy-cy)**2), ang = Math.atan2(wy-cy, wx-cx);
  const sp1 = (Math.sin(dist*0.05-ang*3-t*1.5) + Math.sin(dist*0.04+ang*4-t*1.2))*0.4;
  const sp2 = (Math.sin(dist*0.08-ang*5+t*0.8) + Math.sin(dist*0.06+ang*2-t*2.0))*0.2;
  const sp3 = Math.sin(dist*0.12+ang*7-t*3.0)*0.1;
  const spiral = sp1 + sp2 + sp3;
  const cell = Math.tanh((Math.sin(wx*0.15)*Math.sin(wy*0.15) + Math.sin((wx+wy)*0.1+t)*0.5)*1.5)*0.3;
  const cellFine = Math.tanh((Math.sin(wx*0.3+1)*Math.sin(wy*0.3+2) + Math.sin((wx-wy)*0.2-t*0.7)*0.3)*1.2)*0.15;
  const reaction1 = Math.tanh((act - inh*0.7 + bg*0.3 + spiral)*2.2);
  const reaction2 = Math.tanh((reaction1*0.8 - reaction1*reaction1*0.3 + cell*0.5 + sp2)*1.8);
  const blend = reaction1*0.5 + reaction2*0.3 + cell*0.12 + cellFine*0.08;
  const v = blend*0.5+0.5;
  const pal = [
    [5,10,45],[12,45,85],[18,95,115],[25,155,130],[80,185,120],
    [180,200,80],[220,190,60],[215,140,55],[200,100,60],[175,60,65],
    [130,35,70],[85,20,65],[45,15,55],[15,12,50],[5,10,45]
  ];
  const idx = v*(pal.length-1), i = Math.min(idx|0, pal.length-2), f = idx-i;
  const lum = 0.8 + Math.sin(reaction1*Math.PI)*0.2 + Math.sin(reaction2*Math.PI*0.5)*0.05;
  const edge1 = Math.abs(reaction1) > 0.65 ? 1.1 : 1.0;
  const edge2 = Math.abs(reaction2) > 0.5 ? 1.08 : 1.0;
  const sparkle = (Math.abs(aH) > 3.2 && Math.abs(iH) > 2.8) ? 1.2 : 1.0;
  const final = lum * edge1 * edge2 * sparkle;
  return [
    Math.min(255, (pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*final)|0,
    Math.min(255, (pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*final)|0,
    Math.min(255, (pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*final)|0
  ];
}
